const { page } = useBoard()
const [text, setText] = useState(String(column.wipLimit))
const submit = () => void column.submitWipLimit(text)
const pressed = (event: KeyboardEvent) => {
  if (event.key === 'Enter') submit()
  if (event.key === 'Escape') page.layout.cancelLimit()
}
return <input type="number" min="1" className="limit-field" aria-label={`WIP limit for ${column.name}`} value={text} onChange={event => setText(event.target.value)} onBlur={submit} onKeyDown={pressed} autoFocus />

const { page, state } = useBoard()
const limit = column.wipLimit
return (
  <span className={column.isOverLimit ? 'stage-count is-over-limit' : 'stage-count'}>
    <span>{column.count}</span>
    <span>/</span>
    {state.editingLimit === column.name ? (
      <WipLimitFieldView column={column} />
    ) : (
      <button className="limit-button" aria-label={`WIP limit for ${column.name} is ${limit}. Edit`} title="Edit WIP limit" onClick={() => page.layout.editLimit(column.name)}>
        {limit}
      </button>
    )}
  </span>
)

const { page } = useBoard()
return (
  <div className="edge-head">
    <span>{column.name.toUpperCase()}</span>
    <span className="edge-count">
      <span>{column.count}</span>
      {column.isBacklog ? (
        <button className="icon-button add-item" aria-label="New backlog ticket" title="New backlog ticket" onClick={() => page.draft.open()}>
          +
        </button>
      ) : null}
    </span>
  </div>
)

const { state } = useBoard()
return (
  <div className="board-column" data-column={column.name}>
    <EdgeHeadView column={column} />
    {column.isBacklog && state.draft.isOpen ? <ComposerView /> : null}
    <div className="card-lists is-single">
      <DropZoneView className="card-list" accepts={ticket => ticket.canDropOn(column.name)} onDrop={ticket => ticket.dropOn(column.name)}>
        {column.items.map(item => (
          <BacklogCardView key={item.path} item={item} />
        ))}
        <TicketListView tickets={column.tickets} spot="only" />
      </DropZoneView>
    </div>
  </div>
)

const { page, state } = useBoard()
const [isOver, setOver] = useState(false)
// Read when each event arrives, not from the last drawing: a quick drag reaches the list before the page redraws.
const draggedNow = () => {
  const address = page.store.state.dragged
  const ticket = page.board.ticketAt(address)
  const item = onItemDrop ? page.board.backlogItems.find(entry => entry.address === address) : undefined
  return { ticket, item, isAccepted: (ticket !== undefined && (ticket.isStacked || accepts(ticket))) || item !== undefined }
}
const isAccepted = state.dragged !== null && draggedNow().isAccepted
const draggedOver = (event: DragEvent) => {
  if (!draggedNow().isAccepted) return
  event.preventDefault()
  setOver(true)
}
const dropped = (event: DragEvent) => {
  event.preventDefault()
  setOver(false)
  const { ticket, item, isAccepted: wasAccepted } = draggedNow()
  page.store.change({ dragged: null })
  if (item && onItemDrop) void onItemDrop(item)
  else if (ticket?.isStacked) void leaveParent(ticket, event)
  else if (ticket && wasAccepted) void onDrop(ticket)
}
const shown = [className, isAccepted ? 'is-drop-zone' : '', isAccepted && isOver ? 'is-drop-over' : ''].filter(Boolean).join(' ')
return (
  <div className={shown} onDragOver={draggedOver} onDragLeave={() => setOver(false)} onDrop={dropped}>
    {children}
  </div>
)

const { page } = useBoard()
const accepts = (ticket: TicketClient) => !(ticket.column.name === column.name && ticket.isDone === done)
const startsItems = !done && page.board.stages[0]?.name === column.name
return (
  <DropZoneView className="card-list" accepts={accepts} onDrop={ticket => ticket.moveTo(column.name, done)} onItemDrop={startsItems ? item => page.roots.openToStart(item) : undefined}>
    {children}
  </DropZoneView>
)

return (
  <>
    {tickets.map(ticket => (
      <TicketCardView key={ticket.address} ticket={ticket} spot={spot} />
    ))}
  </>
)

const { page, state } = useBoard()
useKeptSelection()
return (
  <section className="board-region" aria-label="Board" style={{ flexBasis: state.expandedRegion ? 0 : state.boardHeight, flexGrow: state.expandedRegion ? 1 : 0 }}>
    {state.board && !state.serverFailure ? (
      <div className="column-grid">
        {page.board.shownColumns.map(column => (column.isStage ? <StageColumnView key={column.name} column={column} /> : <EdgeColumnView key={column.name} column={column} />))}
      </div>
    ) : (
      <WaitingView hasFailed={state.serverFailure !== null} />
    )}
  </section>
)

const { page, state } = useBoard()
const isGone = state.board !== null && state.openCard !== null && !page.board.tickets.some(ticket => ticket.name === state.openCard)
useEffect(() => {
  if (isGone && state.openCard) page.cards.releaseTicket(state.openCard)
}, [isGone, page, state.openCard])

const headline = headlineOf(failure)
return (
  <div className="band band-failure" role="alert">
    {startingOf(failure)} The board shows no columns until it answers, and tries again every two seconds · {headline}
    {headline !== failure.trim() ? (
      <details className="band-details">
        <summary>Details</summary>
        <pre>{failure}</pre>
      </details>
    ) : null}
  </div>
)

const { page } = useBoard()
return (
  <div className="band band-failure" role="alert" aria-label="Changes not saved">
    Not saved on main: {changes.join('; ')} · {headlineOf(error)}
    <button className="action" onClick={() => void page.board.saveAgain()}>
      Save again
    </button>
  </div>
)

return (
  <div className="band" role="status" aria-label="Active ticket's violations">
    <span className="band-words">
      {ticket.name} · {ticket.column.name} · violations: {ticket.violatedSlugs.join(', ')}
    </span>
  </div>
)

const { page, state } = useBoard()
if (state.serverFailure) return <ServerBandView failure={state.serverFailure} />
const active = page.board.activeTicket
return (
  <>
    {page.board.unsaved ? <UnsavedBandView changes={page.board.unsaved.changes} error={page.board.unsaved.error} /> : null}
    {active?.violatedSlugs.length ? <ViolationsBandView ticket={active} /> : null}
  </>
)

const { page, state } = useBoard()
const grip = useDragGrip(
  'y',
  () => state.boardHeight,
  (height, distance, element) => page.layout.setBoardHeight(height + distance, element.closest('main')?.clientHeight ?? 0),
)
return (
  <div className="split-bar">
    <button className="grip" aria-label="Drag to resize the board and the details" {...grip}>
      <span className="grip-line" />
    </button>
  </div>
)

const { state } = useBoard()
return (
  <div className="toasts">
    {state.toasts.map(toast => (
      <div key={toast.id} role="status" className={toast.isFailure ? 'toast toast-failure' : 'toast'}>
        {toast.text}
      </div>
    ))}
  </div>
)

const { state } = useBoard()
const isCovered = state.panels.some(panel => panel.isExpanded)
const { expandedRegion, serverFailure } = state
return (
  <main className={isCovered ? 'board-main is-covered' : 'board-main'}>
    <BoardHeaderView />
    {expandedRegion !== 'details' ? <BoardColumnsView /> : null}
    {expandedRegion ? null : <SplitGripView />}
    {expandedRegion !== 'board' && !serverFailure ? <DetailsView /> : null}
  </main>
)

const { page, state } = useBoard()
useEffect(() => page.start(), [page])
// A page left open across a rebuild loads the new build, so it never shows the old code.
useEffect(() => {
  if (state.isNewBuild) globalThis.location.reload()
}, [state.isNewBuild])
return (
  <div className="board-root">
    <BandsView />
    <div className="page-body">
      <MainView />
      <SidePanelsView />
    </div>
    <ActivationView />
    <RootChoiceView />
    <ToastsView />
  </div>
)

if (!this.state.failure) return this.props.children
return (
  <div className="band band-failure" role="alert">
    The board page failed: {this.state.failure}
    <button className="action" onClick={() => location.reload()}>
      Reload
    </button>
  </div>
)

const asked: string[] = []
const send = (path: string) => {
  asked.push(path)
  return new Promise<Response>(() => undefined)
}
return { asked, send }

const page = new BoardPage(slowServer().send)
page.store.change({ board: boardRead() })
return page

const page = new BoardPage(slowServer().send)
page.store.change({ board: boardRead(), serverFailure: 'The cdd server is not connected: connect.py failed' })
return renderToString(createElement(BoardPageView, { page }))

const progress = { fidelity: { slug: 'stories-story-map' }, stage: { name: 'Discovery' }, state: 'not_started', is_enabled: true }
const ticket = { name: 'sign-up', title: 'Sign up', column: { name: 'Discovery' }, progress: [progress], stage_work: [], next: null }
const practice = { key: 'stories', slug: 'stories', short_name: 'Stories', colour: '#000' }
return {
  project: 'shop',
  practices: [practice],
  fidelities: [{ fidelity: { slug: 'stories-story-map' }, practice: { key: 'stories' }, label: 'Story map', skill: '/x' }],
  open_tickets: [],
  active: null,
  columns: [{ name: 'Discovery', kind: 'stage', in_progress: [ticket], done: [] }],
} as unknown as BoardData

const own = chat.name || chat.id
const isShared = this.store.state.chats.some(other => other.id !== chat.id && (other.name || other.id) === own)
return isShared ? `${own} (${chat.id.slice(0, SHOWN_CHAT_ID)})` : own

if (this.store.state.isUpdating) return
this.store.change({ isUpdating: true })
this.store.toast('Updating: getting the latest code, re-pinning cdd, and rebuilding')
const updated = await this.api.post<{ is_updated: boolean }>(UPDATE_PATH)
if (updated && (await this.boardServerIsBack())) this.store.change({ isNewBuild: true })
this.store.change({ isUpdating: false })

for (let waited = 0; waited < SERVER_BACK_WITHIN_MILLISECONDS; waited += SERVER_BACK_CHECK_MILLISECONDS) {
  await this.pause(SERVER_BACK_CHECK_MILLISECONDS)
  if ((await this.build.served()) !== null) return true
}
this.store.toast('The board server did not come back after the update; run /board in a chat to start it.', true)
return false

const query = new URLSearchParams(search)
const name = query.get(REPORT_QUERY)
const slug = query.get(FIDELITY_QUERY)
if (!name || !slug) return
if (!this.store.state.board) await this.reader.refresh()
const ticket = this.board.tickets.find(shown => shown.name === name)
const progress = ticket?.progressNamed(slug)
if (!ticket || !progress) return this.store.toast(`The board has no ${slug} report for ${name}.`, true)
this.store.change({ selected: ticket.address })
await this.panels.openReport(ticket, progress)

void this.openLinkedReport(typeof location === 'undefined' ? '' : location.search)
const stopBoard = this.reader.startPolling()
const chatTimer = setInterval(() => void this.pollChats(), CHAT_POLL_MILLISECONDS)
void this.pollChats()
return () => {
  stopBoard()
  clearInterval(chatTimer)
}

if (this.isPollingChats) return
this.isPollingChats = true
await Promise.all([this.chat.refresh(), this.build.check()]).finally(() => {
  this.isPollingChats = false
})

const response = await this.send(SERVED_PAGE, { cache: 'no-store' }).catch(() => null)
if (!response) {
  this.store.change({ serverFailure: BOARD_SERVER_DOWN })
  return null
}
return response.ok ? response.text() : ''

const served = await this.served()
if (served === null) return
this.loaded ??= served
if (served !== this.loaded) this.store.change({ isNewBuild: true })

const posted: string[] = []
const api: CddApi = {
  post: async <Result>(path: string) => {
    posted.push(path)
    return { ...app, status } as unknown as Result
  },
}
return { api, posted }

const opened = await app.open()
if (!opened) return
if (opened.status !== 'running') {
  this.store.toast(`The ${opened.label} app is ${opened.status}: open it from the chat bar's status row, which starts it for that chat.`, true)
  return
}
const page = new URL(opened.url)
page.searchParams.set(PROJECT_QUERY, project)
this.openWindow(page.toString())

return readdirSync(folder).flatMap(name => {
  const path = join(folder, name)
  if (statSync(path).isDirectory()) return pageSources(path)
  return /\.tsx?$/.test(name) && !name.endsWith('.spec.ts') ? [path] : []
})

def _(world):
    CHECKOUT_FLOW.seed_into(world.project)
    BILLING_REPORT.seed_into(world.project)

@s.when("the Person opens the knowledge graph from checkout-flow's graph widget")
def _(world):
    world.graph = world.board().ticket(CHECKOUT_FLOW.name).session.graph
    world.graph.load_practice_roots(world.app_call())

@s.then("the Graph app opens on checkout-flow's practice roots: harness/.context/stories, harness/.context/ux and harness/.context")
def _(world):
    expect(roots_loaded(world.graph, world.project.root)).to(equal(CHECKOUT_FLOW.roots))

@s.and_("no folder of billing-report is loaded")
def _(world):
    expect(files_read(world.graph, world.project.root)).to(equal([f"{CHECKOUT_FLOW.roots['stories']}/story-map.md"]))

const read = this.store.state.board ?? NOT_READ_YET
if (this.shown?.read !== read) this.shown = new BoardClient(read, this)
return this.shown
